import heapq

class Counted:
    comparisons = 0
    def __init__(self, v):
        self.v = v
    def __lt__(self, other):
        Counted.comparisons += 1
        return self.v < other.v

x, vals = 7, []
for _ in range(500):
    x = (x * 1103515245 + 12345) % 2**31
    vals.append(x % 10000)

def cost(fn):
    Counted.comparisons = 0
    fn([Counted(v) for v in vals])
    return Counted.comparisons

print("sorted:", cost(sorted))
print("min:", cost(min))
print("nsmallest(3):", cost(lambda items: heapq.nsmallest(3, items)))
